# Generated by scripts/update-formula.sh from the v0.1.31 release. Don't edit by hand.
class Quietmouse < Formula
  desc "Offline, telemetry-free settings, buttons and gestures for Logitech mice"
  homepage "https://github.com/benjweaver/quietmouse"
  license "GPL-3.0-or-later"

  livecheck do
    url :homepage
    strategy :github_latest
  end

  # One universal archive serves both Apple Silicon and Intel Macs.
  on_macos do
    on_arm do
      url "https://github.com/benjweaver/quietmouse/releases/download/v0.1.31/quietmouse-v0.1.31-macos-universal.tar.gz"
      sha256 "3b02f980102c4ad038cfc9383e16d82f4a1c02a409ff5a3d5e0e17fae73ab125"
    end
    on_intel do
      url "https://github.com/benjweaver/quietmouse/releases/download/v0.1.31/quietmouse-v0.1.31-macos-universal.tar.gz"
      sha256 "3b02f980102c4ad038cfc9383e16d82f4a1c02a409ff5a3d5e0e17fae73ab125"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/benjweaver/quietmouse/releases/download/v0.1.31/quietmouse-v0.1.31-linux-x86_64.tar.gz"
      sha256 "d38ff288674da3a34d5751e7c2472f0e6e6e1ba5cd47dd1ed22293ad5fb0bbb5"
    end
  end

  def install
    bin.install "quietmouse"
    # On macOS quietmoused's real binary lives inside a minimal .app bundle, so
    # Privacy & Security and Login Items show it by name, with its icon; a bare
    # binary has no bundle for those lists to read either from. The bundle also
    # carries the LaunchAgent that "quietmouse autostart on" registers.
    # quietmoused itself has to go in as a symlink into the bundle, not the
    # bundle directly: brew link only symlinks individual files out of a keg's
    # bin into the shared bin it puts on PATH, silently skipping whole
    # directories, so the bundle would never reach it. Linux has no such lists,
    # so it stays a bare binary there.
    if OS.mac?
      # quietmouse.app from 0.1.30; quietmoused.app before.
      app = File.exist?("quietmouse.app") ? "quietmouse.app" : "quietmoused.app"
      bin.install app
      bin.install_symlink "#{app}/Contents/MacOS/quietmoused" => "quietmoused"
    else
      bin.install "quietmoused"
    end
    pkgshare.install Dir["**/70-quietmouse.rules", "**/modules-load.conf"] if OS.linux?
    # Releases before 0.1.9 don't carry the notices.
    doc.install "THIRD-PARTY-NOTICES.md" if File.exist?("THIRD-PARTY-NOTICES.md")
  end

  def caveats
    message = <<~TEXT
      Write a config, then start quietmouse now and whenever you log in:
        quietmouse config --init
        quietmouse autostart on
    TEXT
    if OS.mac?
      message + <<~TEXT

        On macOS, quietmouse asks for Input Monitoring and Accessibility (called
        Device Control and Data Access on newer macOS) when the agent starts, so
        macOS prompts and lists it ready to switch on.

        After upgrading, run "quietmouse autostart on" to point at the new
        version. The switches carry over, since releases are signed with a
        Developer ID; upgrading from 0.1.28 or earlier asks once more. On
        macOS 27 it's listed once, under Device Control and Data Access.
      TEXT
    else
      message + <<~TEXT

        On Linux, install the udev rule once so your user can open Logitech devices:
          sudo install -m 644 #{pkgshare}/70-quietmouse.rules /etc/udev/rules.d/
          sudo udevadm control --reload
          sudo udevadm trigger
      TEXT
    end
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/quietmouse --version")
    system bin/"quietmouse", "config", "--init"
    system bin/"quietmouse", "config", "--check"
  end
end
